import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum LeadSource {
  INSTAGRAM = 'Instagram',
  WEBSITE = 'Website',
  ADVERTISING = 'Advertising',
  COLD_CALL = 'Cold Call',
  TELEGRAM = 'Telegram'
}

export enum DealStage {
  NEW_LEAD = 'New Lead',
  CONTACTED = 'Contacted',
  NEEDS_ANALYSIS = 'Needs Analysis',
  PROPOSAL = 'Proposal',
  NEGOTIATION = 'Negotiation',
  CLOSED_WON = 'Closed Won',
  CLOSED_LOST = 'Closed Lost'
}

export interface Contact {
  id: string;
  name: string;
  email: string;
  phone: string;
  company: string;
  role: string;
  source: LeadSource;
  tags: string[];
  notes: string;
  lastContacted: string;
  status: 'Active' | 'Inactive' | 'Pending';
}

export interface Deal {
  id: string;
  title: string;
  amount: number;
  contactId: string;
  stage: DealStage;
  expectedCloseDate: string;
  priority: 'Low' | 'Medium' | 'High';
}

export interface Task {
  id: string;
  title: string;
  dueDate: string;
  assignedTo: string;
  completed: boolean;
  priority: 'Low' | 'Medium' | 'High';
}

export interface Message {
  id: string;
  sender: 'User' | 'AI' | 'Customer';
  text: string;
  timestamp: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeLeadQuality = async (contactData: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze this CRM lead data and provide a quality score (0-100) and 3 short actionable tips for the sales manager.
      Lead Data: ${contactData}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            summary: { type: Type.STRING },
            tips: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            }
          },
          required: ["score", "summary", "tips"]
        }
      }
    });
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Gemini Lead Analysis failed:", error);
    return null;
  }
};

export const generateSmartResponse = async (chatHistory: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `You are an AI Sales Assistant within a CRM system. Based on the chat history, suggest a professional response to the customer to move the deal forward.
      History: ${chatHistory}`,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini smart response failed:", error);
    return "I am sorry, I am currently unable to generate a response.";
  }
};

