import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import TopBar from './components/TopBar';
import Dashboard from './components/Dashboard';
import ContactsList from './components/ContactsList';
import DealsBoard from './components/DealsBoard';
import { Bot, X, Send, Sparkles } from 'lucide-react';
import { generateSmartResponse } from './services/geminiService';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState('dashboard');
  const [isDark, setIsDark] = useState(false);
  const [isAIChatOpen, setIsAIChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: string, text: string}[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  const handleSendMessage = async () => {
    if (!chatMessage.trim()) return;

    const userMsg = chatMessage;
    setChatMessage('');
    setChatHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    const response = await generateSmartResponse(JSON.stringify([...chatHistory, { role: 'user', text: userMsg }]));

    setIsTyping(false);
    setChatHistory(prev => [...prev, { role: 'ai', text: response || "I'm sorry, I'm having trouble thinking." }]);
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard isDark={isDark} />;
      case 'contacts': return <ContactsList isDark={isDark} />;
      case 'deals': return <DealsBoard isDark={isDark} />;
      default: return (
        <div className="flex flex-col items-center justify-center h-full text-center space-y-4 opacity-50">
          <div className="p-8 bg-slate-100 dark:bg-slate-800 rounded-full">
            <Sparkles size={48} className="text-indigo-500" />
          </div>
          <div>
             <h2 className="text-xl font-bold">Under Construction</h2>
             <p>This module is currently being optimized for your business needs.</p>
          </div>
        </div>
      );
    }
  };

  return (
    <div className={`flex h-screen w-full transition-colors duration-200 ${isDark ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`}>
      <Sidebar activeView={activeView} setActiveView={setActiveView} isDark={isDark} />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <TopBar isDark={isDark} setIsDark={setIsDark} />

        <main className="flex-1 overflow-y-auto p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto h-full">
            {renderView()}
          </div>
        </main>

        {/* Floating AI Assistant Trigger */}
        <button 
          onClick={() => setIsAIChatOpen(!isAIChatOpen)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-40 group"
        >
          {isAIChatOpen ? <X size={24} /> : <Bot size={24} />}
          <span className="absolute right-16 px-3 py-1 bg-white dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 rounded-lg text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity shadow-lg pointer-events-none">
            Ask Nova AI Assistant
          </span>
        </button>

        {/* AI Chat Drawer */}
        {isAIChatOpen && (
          <div className={`fixed bottom-24 right-8 w-96 h-[500px] flex flex-col shadow-2xl rounded-2xl border z-40 overflow-hidden transition-all duration-300 animate-in slide-in-from-bottom-5 ${
            isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
          }`}>
            <div className="p-4 bg-indigo-600 text-white flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Bot size={20} />
                <span className="font-bold">Nova AI Sales Assistant</span>
              </div>
              <Sparkles size={16} className="animate-pulse" />
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-slate-50 dark:bg-slate-900/50">
              {chatHistory.length === 0 && (
                <div className="text-center mt-12 opacity-50 space-y-2">
                  <p className="text-sm">Hello! I'm your business co-pilot.</p>
                  <p className="text-xs italic">Ask me about leads, revenue projections, or sales strategies.</p>
                </div>
              )}
              {chatHistory.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                    msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-tr-none shadow-md shadow-indigo-500/20' 
                    : `${isDark ? 'bg-slate-800 text-slate-200' : 'bg-white text-slate-800'} border rounded-tl-none shadow-sm`
                  }`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className={`p-3 rounded-2xl text-sm ${isDark ? 'bg-slate-800' : 'bg-white'} border rounded-tl-none flex gap-1`}>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                  </div>
                </div>
              )}
            </div>

            <div className={`p-4 border-t ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <div className="relative">
                <input 
                  type="text" 
                  value={chatMessage}
                  onChange={(e) => setChatMessage(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                  placeholder="Type your question..."
                  className={`w-full pl-4 pr-12 py-3 rounded-xl border text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition-all ${
                    isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'
                  }`}
                />
                <button 
                  onClick={handleSendMessage}
                  className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-indigo-600 text-white rounded-lg flex items-center justify-center hover:bg-indigo-700 transition-colors"
                >
                  <Send size={16} />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

