                    <img className="w-10 h-10 rounded-full object-cover" src={`https://picsum.photos/40/40?u=${contact.id}`} alt="" />
                    <div>
                      <div className={`font-semibold text-sm ${isDark ? 'text-white' : 'text-slate-900'}`}>{contact.name}</div>
                      <div className="text-xs text-slate-500">{contact.role} @ {contact.company}</div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase ${
                    contact.status === 'Active' ? 'bg-emerald-100 text-emerald-600' :
                    contact.status === 'Pending' ? 'bg-amber-100 text-amber-600' : 'bg-slate-100 text-slate-600'
