export const analyzeLeadQuality = async (contactData: string) => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Проанализируй данные этого лида в CRM и предоставь оценку качества (0-100), краткое резюме и 3 конкретных совета для менеджера по продажам.
      ОТВЕТ ДОЛЖЕН БЫТЬ ТОЛЬКО НА РУССКОМ ЯЗЫКЕ В ФОРМАТЕ JSON.
      Данные лида: ${contactData}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: { type: Type.NUMBER },
            summary: { type: Type.STRING },
            tips: { 
              type: Type.ARRAY, 
              items: { type: Type.STRING } 
            }
          },
          required: ["score", "summary", "tips"]
        }
      }
    });
    const text = response.text;
    return text ? JSON.parse(text) : null;
