import React, { useState } from 'react';
import { DealStage, Deal } from '../types';
import { MOCK_DEALS } from '../constants';
import { MoreHorizontal, Plus, Calendar, DollarSign } from 'lucide-react';

const STAGES = [
  DealStage.NEW_LEAD,
  DealStage.CONTACTED,
  DealStage.PROPOSAL,
  DealStage.NEGOTIATION,
  DealStage.CLOSED_WON
];

const DealsBoard: React.FC<{ isDark: boolean }> = ({ isDark }) => {
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);

  const getStageColor = (stage: DealStage) => {
    switch (stage) {
      case DealStage.NEW_LEAD: return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
      case DealStage.CONTACTED: return 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400';
      case DealStage.PROPOSAL: return 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400';
      case DealStage.NEGOTIATION: return 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400';
      case DealStage.CLOSED_WON: return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  return (
    <div className="h-full overflow-x-auto custom-scrollbar flex gap-6 pb-6">
      {STAGES.map((stage) => (
        <div key={stage} className="flex-shrink-0 w-80 flex flex-col">
          <div className="flex items-center justify-between mb-4 px-2">
            <div className="flex items-center gap-2">
              <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-md ${getStageColor(stage)}`}>
                {stage}
              </span>
              <span className={`text-xs font-medium ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>
                ({deals.filter(d => d.stage === stage).length})
              </span>
            </div>
            <button className={`p-1 rounded hover:${isDark ? 'bg-slate-800' : 'bg-slate-100'} transition-colors text-slate-400`}>
              <Plus size={16} />
            </button>
          </div>

          <div className={`flex-1 rounded-xl p-2 space-y-3 kanban-column min-h-[400px] ${isDark ? 'bg-slate-900/50' : 'bg-slate-100/50'}`}>
            {deals.filter(d => d.stage === stage).map((deal) => (
              <div 
                key={deal.id}
                className={`p-4 rounded-xl border shadow-sm transition-transform hover:scale-[1.02] cursor-grab active:cursor-grabbing ${
                  isDark ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-200'
                }`}
              >
                <div className="flex justify-between items-start mb-2">
                  <h4 className="font-semibold text-sm">{deal.title}</h4>
                  <button className="text-slate-400 hover:text-slate-600">
                    <MoreHorizontal size={14} />
                  </button>
                </div>

                <div className="flex flex-col gap-2 mb-4">
                   <div className="flex items-center gap-1.5 text-xs text-slate-500">
                     <DollarSign size={12} className="text-emerald-500" />
                     <span className="font-bold text-slate-700 dark:text-slate-300">₽{deal.amount.toLocaleString()}</span>
                   </div>
                   <div className="flex items-center gap-1.5 text-xs text-slate-500">
                     <Calendar size={12} />
                     <span>Закрытие: {deal.expectedCloseDate}</span>
                   </div>
                </div>

                <div className="flex items-center justify-between">
                  <div className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${
                    deal.priority === 'Высокий' ? 'bg-rose-100 text-rose-600' : 
                    deal.priority === 'Средний' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'
                  }`}>
                    {deal.priority}
                  </div>
                  <div className="flex -space-x-2">
                    <img className="w-6 h-6 rounded-full border-2 border-white dark:border-slate-900" src={`https://picsum.photos/32/32?u=${deal.id}`} alt="avatar" />
                  </div>
                </div>
              </div>
            ))}

            {deals.filter(d => d.stage === stage).length === 0 && (
               <div className="h-24 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-xl flex items-center justify-center text-slate-400 text-xs">
                 Перетащите сделку
               </div>
            )}
          </div>
        </div>
      ))}
    </div>
  );
};

export default DealsBoard;

