import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import TopBar from './components/TopBar';
import Dashboard from './components/Dashboard';
import ContactsList from './components/ContactsList';
import DealsBoard from './components/DealsBoard';
import TasksList from './components/TasksList';
import TeamView from './components/TeamView';
import AnalyticsView from './components/AnalyticsView';
import CommunicationsCenter from './components/CommunicationsCenter';
import FinanceView from './components/FinanceView';
import ServiceDesk from './components/ServiceDesk';
import IntegrationsView from './components/IntegrationsView';
import SettingsView from './components/SettingsView';
import { Bot, X, Send, Sparkles } from 'lucide-react';
import { generateSmartResponse } from './services/geminiService';

const App: React.FC = () => {
  const [activeView, setActiveView] = useState('dashboard');
  const [isDark, setIsDark] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAIChatOpen, setIsAIChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: string, text: string}[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  const handleSendMessage = async () => {
    if (!chatMessage.trim()) return;

    const userMsg = chatMessage;
    setChatMessage('');
    setChatHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    const response = await generateSmartResponse(JSON.stringify([...chatHistory, { role: 'user', text: userMsg }]));

    setIsTyping(false);
    setChatHistory(prev => [...prev, { role: 'ai', text: response || "Извините, возникла ошибка при обработке запроса." }]);
  };

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <Dashboard isDark={isDark} />;
      case 'contacts': return <ContactsList isDark={isDark} />;
      case 'deals': return <DealsBoard isDark={isDark} />;
      case 'tasks': return <TasksList isDark={isDark} />;
      case 'team': return <TeamView isDark={isDark} />;
      case 'analytics': return <AnalyticsView isDark={isDark} />;
      case 'communications': return <CommunicationsCenter isDark={isDark} />;
      case 'finance': return <FinanceView isDark={isDark} />;
      case 'service': return <ServiceDesk isDark={isDark} />;
      case 'integrations': return <IntegrationsView isDark={isDark} />;
      case 'settings': return <SettingsView isDark={isDark} />;
      default: return (
        <div className="flex flex-col items-center justify-center h-full text-center space-y-4 opacity-50">
          <div className="p-8 bg-slate-100 dark:bg-slate-800 rounded-full">
            <Sparkles size={48} className="text-indigo-500" />
          </div>
          <div>
             <h2 className="text-xl font-bold">Модуль не найден</h2>
             <p>Пожалуйста, выберите существующий раздел в меню.</p>
          </div>
        </div>
      );
    }
  };

  return (
    <div className={`flex h-screen w-full transition-colors duration-200 ${isDark ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`}>
      <Sidebar 
        activeView={activeView} 
        setActiveView={setActiveView} 
        isDark={isDark} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <TopBar 
          isDark={isDark} 
          setIsDark={setIsDark} 
          toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} 
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto h-full">
            {renderView()}
          </div>
        </main>

        <button 
          onClick={() => setIsAIChatOpen(!isAIChatOpen)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-40 group"
        >
          {isAIChatOpen ? <X size={24} /> : <Bot size={24} />}
          <span className="absolute right-16 px-3 py-1 bg-white dark:bg-slate-800 text-indigo-600 dark:text-indigo-400 rounded-lg text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity shadow-lg pointer-events-none">
            Спросить Nova AI
          </span>
        </button>

        {isAIChatOpen && (
          <div className={`fixed bottom-24 right-8 w-full max-w-[calc(100%-2rem)] md:w-96 h-[500px] flex flex-col shadow-2xl rounded-2xl border z-50 overflow-hidden transition-all duration-300 animate-in slide-in-from-bottom-5 ${
            isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
          }`}>
            <div className="p-4 bg-indigo-600 text-white flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Bot size={20} />
                <span className="font-bold">Ассистент Nova AI</span>
              </div>
              <Sparkles size={16} className="animate-pulse" />
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-slate-50 dark:bg-slate-900/50">
              {chatHistory.length === 0 && (
                <div className="text-center mt-12 opacity-50 space-y-2">
                  <p className="text-sm">Здравствуйте! Я ваш бизнес-ассистент.</p>
                  <p className="text-xs italic">Спросите меня о лидах, прогнозе выручки или стратегии продаж.</p>
                </div>
              )}
              {chatHistory.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${
                    msg.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-tr-none shadow-md shadow-indigo-500/20' 
                    : `${isDark ? 'bg-slate-800 text-slate-200' : 'bg-white text-slate-800'} border rounded-tl-none shadow-sm`
                  }`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className={`p-3 rounded-2xl text-sm ${isDark ? 'bg-slate-800' : 'bg-white'} border rounded-tl-none flex gap-1`}>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                    <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce [animation-delay:0.4s]"></div>
                  </div>
                </div>
              )}
            </div>

            <div className={`p-4 border-t ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
              <div className="relative">
                <input 
                  type="text" 
                  value={chatMessage}
                  onChange={(e) => setChatMessage(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                  placeholder="Введите сообщение..."
                  className={`w-full pl-4 pr-12 py-3 rounded-xl border text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition-all ${
                    isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'
                  }`}
                />
                <button 
                  onClick={handleSendMessage}
                  className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-indigo-600 text-white rounded-lg flex items-center justify-center hover:bg-indigo-700 transition-colors"
                >
                  <Send size={16} />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import TopBar from './components/TopBar';
import Dashboard from './components/Dashboard';
import ContactsList from './components/ContactsList';
import DealsBoard from './components/DealsBoard';
import TasksList from './components/TasksList';
import TeamView from './components/TeamView';
import AnalyticsView from './components/AnalyticsView';
import CommunicationsCenter from './components/CommunicationsCenter';
import FinanceView from './components/FinanceView';
import ServiceDesk from './components/ServiceDesk';
import IntegrationsView from './components/IntegrationsView';
import SettingsView from './components/SettingsView';
import { Bot, X, Send, Sparkles } from 'lucide-react';
import { generateSmartResponse } from './services/geminiService';
import { MOCK_CONTACTS, MOCK_TEAM, MOCK_DEALS, MOCK_TASKS } from './constants';
import { Contact, TeamMember, Deal, Task } from './types';

const App: React.FC = () => {
  // Центральное состояние данных
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [team, setTeam] = useState<TeamMember[]>(MOCK_TEAM);
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);
  const [tasks, setTasks] = useState<Task[]>(MOCK_TASKS);

  const [activeView, setActiveView] = useState('dashboard');
  const [isDark, setIsDark] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAIChatOpen, setIsAIChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: string, text: string}[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  const handleSendMessage = async () => {
    if (!chatMessage.trim()) return;

    const userMsg = chatMessage;
    setChatMessage('');
    setChatHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    const response = await generateSmartResponse(JSON.stringify([...chatHistory, { role: 'user', text: userMsg }]));

    setIsTyping(false);
    setChatHistory(prev => [...prev, { role: 'ai', text: response || "Извините, возникла ошибка при обработке запроса." }]);
  };

  const renderView = () => {
    const props = { isDark };
    switch (activeView) {
      case 'dashboard': return <Dashboard {...props} contactsCount={contacts.length} dealsCount={deals.length} />;
      case 'contacts': return <ContactsList {...props} contacts={contacts} setContacts={setContacts} />;
      case 'deals': return <DealsBoard {...props} deals={deals} setDeals={setDeals} />;
      case 'tasks': return <TasksList {...props} tasks={tasks} setTasks={setTasks} />;
      case 'team': return <TeamView {...props} team={team} setTeam={setTeam} />;
      case 'analytics': return <AnalyticsView {...props} />;
      case 'communications': return <CommunicationsCenter {...props} />;
      case 'finance': return <FinanceView {...props} />;
      case 'service': return <ServiceDesk {...props} />;
      case 'integrations': return <IntegrationsView {...props} />;
      case 'settings': return <SettingsView {...props} />;
      default: return (
        <div className="flex flex-col items-center justify-center h-full text-center space-y-4 opacity-50">
          <Sparkles size={48} className="text-indigo-500" />
          <h2 className="text-xl font-bold">Модуль в разработке</h2>
        </div>
      );
    }
  };

  return (
    <div className={`flex h-screen w-full transition-colors duration-200 ${isDark ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`}>
      <Sidebar 
        activeView={activeView} 
        setActiveView={setActiveView} 
        isDark={isDark} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <TopBar 
          isDark={isDark} 
          setIsDark={setIsDark} 
          toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} 
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto h-full">
            {renderView()}
          </div>
        </main>

        <button 
          onClick={() => setIsAIChatOpen(!isAIChatOpen)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-40 group"
        >
          {isAIChatOpen ? <X size={24} /> : <Bot size={24} />}
        </button>

        {isAIChatOpen && (
          <div className={`fixed bottom-24 right-8 w-full max-w-[calc(100%-2rem)] md:w-96 h-[500px] flex flex-col shadow-2xl rounded-2xl border z-50 overflow-hidden transition-all duration-300 animate-in slide-in-from-bottom-5 ${
            isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
          }`}>
            <div className="p-4 bg-indigo-600 text-white flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Bot size={20} />
                <span className="font-bold text-sm">Nova AI</span>
              </div>
              <Sparkles size={14} className="animate-pulse" />
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-slate-50 dark:bg-slate-900/50">
              {chatHistory.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${
                    msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none shadow-md' : `${isDark ? 'bg-slate-800' : 'bg-white'} border rounded-tl-none`
                  }`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isTyping && <div className="text-xs text-slate-400 italic">Печатает...</div>}
            </div>

            <div className="p-4 border-t dark:border-slate-800">
              <div className="relative">
                <input 
                  type="text" 
                  value={chatMessage}
                  onChange={(e) => setChatMessage(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                  placeholder="Задайте вопрос..."
                  className={`w-full pl-4 pr-12 py-3 rounded-xl border text-sm focus:ring-2 focus:ring-indigo-500 outline-none ${
                    isDark ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'
                  }`}
                />
                <button onClick={handleSendMessage} className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-indigo-600 text-white rounded-lg flex items-center justify-center">
                  <Send size={16} />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, Filter, MoreVertical, Tag, Activity, Zap, Plus, X, User } from 'lucide-react';
import { analyzeLeadQuality } from '../services/geminiService';
import { Contact, LeadSource } from '../types';

interface ContactsListProps {
  isDark: boolean;
  contacts: Contact[];
  setContacts: React.Dispatch<React.SetStateAction<Contact[]>>;
}

const ContactsList: React.FC<ContactsListProps> = ({ isDark, contacts, setContacts }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [analyzingId, setAnalyzingId] = useState<string | null>(null);
  const [analysisResult, setAnalysisResult] = useState<any>(null);

  // Состояние новой формы
  const [newContact, setNewContact] = useState({
    name: '',
    email: '',
    phone: '',
    company: '',
    role: '',
    source: LeadSource.WEBSITE
  });

  const filteredContacts = contacts.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    c.company.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAddContact = (e: React.FormEvent) => {
    e.preventDefault();
    const contact: Contact = {
      ...newContact,
      id: `c${Date.now()}`,
      status: 'Активен',
      tags: ['Новый'],
      notes: '',
      lastContacted: new Date().toISOString().split('T')[0]
    };
    setContacts(prev => [contact, ...prev]);
    setIsModalOpen(false);
    setNewContact({ name: '', email: '', phone: '', company: '', role: '', source: LeadSource.WEBSITE });
  };

  const handleAnalyze = async (contact: Contact) => {
    setAnalyzingId(contact.id);
    const result = await analyzeLeadQuality(JSON.stringify(contact));
    setAnalysisResult(result);
    setAnalyzingId(null);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-slate-900'}`}>База клиентов</h2>
          <p className={isDark ? 'text-slate-400' : 'text-slate-500'}>Всего контактов: {contacts.length}</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-500/20"
        >
          <Plus size={18} />
          Добавить лид
        </button>
      </div>

      <div className={`p-4 rounded-xl border flex flex-wrap gap-4 items-center ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
        <div className="flex-1 relative min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Поиск..." 
            className={`w-full pl-10 pr-4 py-2 rounded-lg border focus:ring-2 focus:ring-indigo-500 outline-none ${
              isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'
            }`}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button className={`flex items-center gap-2 px-4 py-2 rounded-lg border ${isDark ? 'border-slate-700 text-slate-300' : 'border-slate-200 text-slate-600'}`}>
          <Filter size={18} /> Фильтры
        </button>
      </div>

      <div className={`rounded-xl border overflow-hidden ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className={`text-xs font-semibold uppercase tracking-wider ${isDark ? 'bg-slate-800/50 text-slate-400' : 'bg-slate-50 text-slate-500'}`}>
              <tr>
                <th className="px-6 py-4">Клиент</th>
                <th className="px-6 py-4">Статус</th>
                <th className="px-6 py-4">Источник</th>
                <th className="px-6 py-4 text-right">Действие</th>
              </tr>
            </thead>
            <tbody className={`divide-y ${isDark ? 'divide-slate-800' : 'divide-slate-100'}`}>
              {filteredContacts.map(contact => (
                <tr key={contact.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-800/30">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold">
                        {contact.name[0]}
                      </div>
                      <div>
                        <div className={`font-semibold text-sm ${isDark ? 'text-white' : 'text-slate-900'}`}>{contact.name}</div>
                        <div className="text-xs text-slate-500">{contact.company}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="px-2 py-1 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-600 uppercase">{contact.status}</span>
                  </td>
                  <td className="px-6 py-4 text-xs text-slate-500">{contact.source}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => handleAnalyze(contact)} className={`p-2 rounded-lg hover:bg-violet-50 text-violet-500 ${analyzingId === contact.id ? 'animate-pulse' : ''}`}>
                      <Activity size={18} />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal: Add Contact */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-in fade-in">
          <div className={`max-w-md w-full p-8 rounded-2xl shadow-2xl border ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-100'}`}>
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-xl font-bold">Новый контакт</h3>
              <button onClick={() => setIsModalOpen(false)}><X size={20} /></button>
            </div>
            <form onSubmit={handleAddContact} className="space-y-4">
              <input 
                required
                placeholder="ФИО клиента" 
                className={`w-full p-3 rounded-xl border text-sm outline-none ${isDark ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'}`}
                value={newContact.name}
                onChange={e => setNewContact({...newContact, name: e.target.value})}
              />
              <input 
                required
                type="email"
                placeholder="Email" 
                className={`w-full p-3 rounded-xl border text-sm outline-none ${isDark ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'}`}
                value={newContact.email}
                onChange={e => setNewContact({...newContact, email: e.target.value})}
              />
              <input 
                placeholder="Компания" 
                className={`w-full p-3 rounded-xl border text-sm outline-none ${isDark ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'}`}
                value={newContact.company}
                onChange={e => setNewContact({...newContact, company: e.target.value})}
              />
              <select 
                className={`w-full p-3 rounded-xl border text-sm outline-none ${isDark ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'}`}
                value={newContact.source}
                onChange={e => setNewContact({...newContact, source: e.target.value as LeadSource})}
              >
                {Object.values(LeadSource).map(s => <option key={s} value={s}>{s}</option>)}
              </select>
              <button className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all">
                Создать лид
              </button>
            </form>
          </div>
        </div>
      )}

      {/* AI Analysis Result Modal */}
      {analysisResult && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className={`max-w-md w-full p-8 rounded-2xl border ${isDark ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-100'}`}>
            <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
              <Zap className="text-violet-500" /> AI Анализ: {analysisResult.score}%
            </h3>
            <p className="text-sm mb-6">{analysisResult.summary}</p>
            <div className="space-y-2">
              {analysisResult.tips.map((tip: string, i: number) => (
                <div key={i} className="text-xs bg-indigo-50 dark:bg-indigo-900/30 p-2 rounded-lg">💡 {tip}</div>
              ))}
            </div>
            <button onClick={() => setAnalysisResult(null)} className="w-full mt-6 py-2 border rounded-xl text-sm font-bold">Закрыть</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ContactsList;

