          <Plus size={20} />
          <span className="font-bold">Добавить клиента</span>
        </button>
      </div>

      <div className={`p-4 rounded-2xl border flex flex-wrap gap-4 items-center ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
