import { MOCK_CONTACTS, MOCK_TEAM, MOCK_DEALS, MOCK_TASKS } from './constants';
import { Contact, TeamMember, Deal, Task } from './types';

const App: React.FC = () => {
  // Центральное состояние данных
  const [contacts, setContacts] = useState<Contact[]>(MOCK_CONTACTS);
  const [team, setTeam] = useState<TeamMember[]>(MOCK_TEAM);
  const [deals, setDeals] = useState<Deal[]>(MOCK_DEALS);
  const [tasks, setTasks] = useState<Task[]>(MOCK_TASKS);

  const [activeView, setActiveView] = useState('dashboard');
  const [isDark, setIsDark] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAIChatOpen, setIsAIChatOpen] = useState(false);
  const [chatMessage, setChatMessage] = useState('');
  const [chatHistory, setChatHistory] = useState<{role: string, text: string}[]>([]);
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDark]);

  const handleSendMessage = async () => {
    if (!chatMessage.trim()) return;

    const userMsg = chatMessage;
    setChatMessage('');
    setChatHistory(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsTyping(true);

    const response = await generateSmartResponse(JSON.stringify([...chatHistory, { role: 'user', text: userMsg }]));

    setIsTyping(false);
    setChatHistory(prev => [...prev, { role: 'ai', text: response || "Извините, возникла ошибка при обработке запроса." }]);
  };

  const renderView = () => {
    const props = { isDark };
    switch (activeView) {
      case 'dashboard': return <Dashboard {...props} contactsCount={contacts.length} dealsCount={deals.length} />;
      case 'contacts': return <ContactsList {...props} contacts={contacts} setContacts={setContacts} />;
      case 'deals': return <DealsBoard {...props} deals={deals} setDeals={setDeals} contacts={contacts} />;
      case 'tasks': return <TasksList {...props} tasks={tasks} setTasks={setTasks} team={team} />;
      case 'team': return <TeamView {...props} team={team} setTeam={setTeam} />;
      case 'analytics': return <AnalyticsView {...props} />;
      case 'communications': return <CommunicationsCenter {...props} />;
      case 'finance': return <FinanceView {...props} />;
      case 'service': return <ServiceDesk {...props} />;
      case 'integrations': return <IntegrationsView {...props} />;
      case 'settings': return <SettingsView {...props} />;
      default: return (
        <div className="flex flex-col items-center justify-center h-full text-center space-y-4 opacity-50">
          <Sparkles size={48} className="text-indigo-500" />
          <h2 className="text-xl font-bold">Модуль в разработке</h2>
        </div>
      );
    }
  };

  return (
    <div className={`flex h-screen w-full transition-colors duration-200 ${isDark ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`}>
      <Sidebar 
        activeView={activeView} 
        setActiveView={setActiveView} 
        isDark={isDark} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <TopBar 
          isDark={isDark} 
          setIsDark={setIsDark} 
          toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)} 
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto h-full">
            {renderView()}
          </div>
        </main>

        <button 
          onClick={() => setIsAIChatOpen(!isAIChatOpen)}
          className="fixed bottom-8 right-8 w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:scale-110 active:scale-95 transition-all z-40 group"
        >
          {isAIChatOpen ? <X size={24} /> : <Bot size={24} />}
        </button>

        {isAIChatOpen && (
          <div className={`fixed bottom-24 right-8 w-full max-w-[calc(100%-2rem)] md:w-96 h-[500px] flex flex-col shadow-2xl rounded-2xl border z-50 overflow-hidden transition-all duration-300 animate-in slide-in-from-bottom-5 ${
            isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'
          }`}>
            <div className="p-4 bg-indigo-600 text-white flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Bot size={20} />
                <span className="font-bold text-sm">Nova AI</span>
              </div>
              <Sparkles size={14} className="animate-pulse" />
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-slate-50 dark:bg-slate-900/50">
              {chatHistory.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-3 rounded-2xl text-sm ${
                    msg.role === 'user' ? 'bg-indigo-600 text-white rounded-tr-none shadow-md' : `${isDark ? 'bg-slate-800' : 'bg-white'} border rounded-tl-none`
                  }`}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {isTyping && <div className="text-xs text-slate-400 italic">Печатает...</div>}
            </div>

            <div className="p-4 border-t dark:border-slate-800">
              <div className="relative">
                <input 
                  type="text" 
                  value={chatMessage}
                  onChange={(e) => setChatMessage(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                  placeholder="Задайте вопрос..."
                  className={`w-full pl-4 pr-12 py-3 rounded-xl border text-sm focus:ring-2 focus:ring-indigo-500 outline-none ${
                    isDark ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'
                  }`}
                />
                <button onClick={handleSendMessage} className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 bg-indigo-600 text-white rounded-lg flex items-center justify-center">
                  <Send size={16} />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { DealStage, Deal, Contact } from '../types';
import { MoreHorizontal, Plus, Calendar, DollarSign, X } from 'lucide-react';

const STAGES = [
  DealStage.NEW_LEAD,
  DealStage.CONTACTED,
  DealStage.PROPOSAL,
  DealStage.NEGOTIATION,
  DealStage.CLOSED_WON
];

interface DealsBoardProps {
  isDark: boolean;
  deals: Deal[];
  setDeals: React.Dispatch<React.SetStateAction<Deal[]>>;
  contacts: Contact[];
}

const DealsBoard: React.FC<DealsBoardProps> = ({ isDark, deals, setDeals, contacts }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newDeal, setNewDeal] = useState({
    title: '',
    amount: '',
    contactId: '',
    stage: DealStage.NEW_LEAD,
    expectedCloseDate: '',
    priority: 'Средний' as 'Низкий' | 'Средний' | 'Высокий'
  });

  const getStageColor = (stage: DealStage) => {
    switch (stage) {
      case DealStage.NEW_LEAD: return 'bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-400';
      case DealStage.CONTACTED: return 'bg-blue-100 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400';
      case DealStage.PROPOSAL: return 'bg-amber-100 text-amber-600 dark:bg-amber-900/30 dark:text-amber-400';
      case DealStage.NEGOTIATION: return 'bg-indigo-100 text-indigo-600 dark:bg-indigo-900/30 dark:text-indigo-400';
      case DealStage.CLOSED_WON: return 'bg-emerald-100 text-emerald-600 dark:bg-emerald-900/30 dark:text-emerald-400';
      default: return 'bg-slate-100 text-slate-600';
    }
  };

  const handleAddDeal = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDeal.title || !newDeal.contactId) return;

    const deal: Deal = {
      id: `d${Date.now()}`,
      title: newDeal.title,
      amount: Number(newDeal.amount) || 0,
      contactId: newDeal.contactId,
      stage: newDeal.stage,
      expectedCloseDate: newDeal.expectedCloseDate || new Date().toISOString().split('T')[0],
      priority: newDeal.priority
    };

    setDeals(prev => [...prev, deal]);
    setIsModalOpen(false);
    setNewDeal({
      title: '',
      amount: '',
      contactId: '',
      stage: DealStage.NEW_LEAD,
      expectedCloseDate: '',
      priority: 'Средний'
    });
  };

  const openModalWithStage = (stage: DealStage) => {
    setNewDeal(prev => ({ ...prev, stage }));
    setIsModalOpen(true);
  };

  return (
    <div className="h-full overflow-x-auto custom-scrollbar flex gap-6 pb-6 animate-in fade-in duration-500">
      {STAGES.map((stage) => (
        <div key={stage} className="flex-shrink-0 w-80 flex flex-col">
          <div className="flex items-center justify-between mb-4 px-2">
            <div className="flex items-center gap-2">
              <span className={`text-[10px] font-bold uppercase tracking-wider px-2 py-1 rounded-md ${getStageColor(stage)}`}>
                {stage}
              </span>
              <span className={`text-xs font-medium ${isDark ? 'text-slate-500' : 'text-slate-400'}`}>
                ({deals.filter(d => d.stage === stage).length})
              </span>
            </div>
            <button 
              onClick={() => openModalWithStage(stage)}
              className={`p-1 rounded hover:${isDark ? 'bg-slate-800 text-white' : 'bg-slate-100 text-slate-900'} transition-colors text-slate-400`}
            >
              <Plus size={16} />
            </button>
          </div>

          <div className={`flex-1 rounded-2xl p-2 space-y-3 kanban-column min-h-[400px] border-2 border-dashed ${isDark ? 'bg-slate-900/30 border-slate-800' : 'bg-slate-100/30 border-slate-200'}`}>
            {deals.filter(d => d.stage === stage).map((deal) => (
              <div 
                key={deal.id}
                className={`p-4 rounded-xl border shadow-sm transition-all hover:scale-[1.02] hover:shadow-md cursor-grab active:cursor-grabbing ${
                  isDark ? 'bg-slate-900 border-slate-800 text-white' : 'bg-white border-slate-200'
                }`}
              >
                <div className="flex justify-between items-start mb-2">
                  <h4 className="font-semibold text-sm line-clamp-2">{deal.title}</h4>
                  <button className="text-slate-400 hover:text-slate-600 flex-shrink-0">
                    <MoreHorizontal size={14} />
                  </button>
                </div>

                <div className="flex flex-col gap-2 mb-4">
                   <div className="flex items-center gap-1.5 text-xs text-slate-500">
                     <DollarSign size={12} className="text-emerald-500" />
                     <span className="font-bold text-slate-700 dark:text-slate-300">₽{deal.amount.toLocaleString()}</span>
                   </div>
                   <div className="flex items-center gap-1.5 text-xs text-slate-500">
                     <Calendar size={12} />
                     <span>Закрытие: {deal.expectedCloseDate}</span>
                   </div>
                </div>

                <div className="flex items-center justify-between">
                  <div className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${
                    deal.priority === 'Высокий' ? 'bg-rose-100 text-rose-600' : 
                    deal.priority === 'Средний' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'
                  }`}>
                    {deal.priority}
                  </div>
                  <div className="flex -space-x-2">
                    <img className="w-6 h-6 rounded-full border-2 border-white dark:border-slate-900" src={`https://api.dicebear.com/7.x/avataaars/svg?seed=${deal.id}`} alt="avatar" />
                  </div>
                </div>
              </div>
            ))}

            <button 
              onClick={() => openModalWithStage(stage)}
              className="w-full py-3 border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-xl flex items-center justify-center text-slate-400 text-xs hover:border-indigo-500 hover:text-indigo-500 transition-all group"
            >
              <Plus size={14} className="mr-1 group-hover:scale-110 transition-transform" /> Добавить сделку
            </button>
          </div>
        </div>
      ))}

      {/* Modal Add Deal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className={`max-w-md w-full p-8 rounded-3xl border shadow-2xl animate-in zoom-in-95 duration-300 ${isDark ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-100'}`}>
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-bold">Создать сделку</h3>
              <button 
                onClick={() => setIsModalOpen(false)}
                className={`p-2 rounded-xl hover:${isDark ? 'bg-slate-800' : 'bg-slate-50'} transition-colors`}
              >
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleAddDeal} className="space-y-5">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Название сделки</label>
                <input 
                  required
                  placeholder="Напр: Поставка оборудования" 
                  className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                  value={newDeal.title}
                  onChange={e => setNewDeal({...newDeal, title: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Сумма (₽)</label>
                  <input 
                    type="number"
                    placeholder="0" 
                    className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                    value={newDeal.amount}
                    onChange={e => setNewDeal({...newDeal, amount: e.target.value})}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Приоритет</label>
                  <select 
                    className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                    value={newDeal.priority}
                    onChange={e => setNewDeal({...newDeal, priority: e.target.value as any})}
                  >
                    <option value="Низкий">Низкий</option>
                    <option value="Средний">Средний</option>
                    <option value="Высокий">Высокий</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Клиент</label>
                <select 
                  required
                  className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                  value={newDeal.contactId}
                  onChange={e => setNewDeal({...newDeal, contactId: e.target.value})}
                >
                  <option value="">Выберите клиента...</option>
                  {contacts.map(c => (
                    <option key={c.id} value={c.id}>{c.name} ({c.company})</option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Этап</label>
                  <select 
                    className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                    value={newDeal.stage}
                    onChange={e => setNewDeal({...newDeal, stage: e.target.value as DealStage})}
                  >
                    {STAGES.map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Дата закрытия</label>
                  <input 
                    type="date"
                    className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                    value={newDeal.expectedCloseDate}
                    onChange={e => setNewDeal({...newDeal, expectedCloseDate: e.target.value})}
                  />
                </div>
              </div>

              <button className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-500/30 active:scale-95">
                Запустить сделку
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default DealsBoard;

import React, { useState } from 'react';
import { CheckCircle2, Circle, Clock, Plus, Filter, MoreHorizontal, X, User } from 'lucide-react';
import { Task, TeamMember } from '../types';

interface TasksListProps {
  isDark: boolean;
  tasks: Task[];
  setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
  team: TeamMember[];
}

const TasksList: React.FC<TasksListProps> = ({ isDark, tasks, setTasks, team }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newStatusFilter, setNewStatusFilter] = useState('all');
  const [newTask, setNewTask] = useState({
    title: '',
    dueDate: '',
    assignedTo: '',
    priority: 'Средний' as 'Низкий' | 'Средний' | 'Высокий'
  });

  const toggleTask = (id: string) => {
    setTasks(prev => prev.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const handleAddTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTask.title || !newTask.assignedTo) return;

    const task: Task = {
      id: `t${Date.now()}`,
      title: newTask.title,
      dueDate: newTask.dueDate || new Date().toISOString().split('T')[0],
      assignedTo: newTask.assignedTo,
      completed: false,
      priority: newTask.priority
    };

    setTasks(prev => [task, ...prev]);
    setIsModalOpen(false);
    setNewTask({ title: '', dueDate: '', assignedTo: '', priority: 'Средний' });
  };

  const filteredTasks = tasks.filter(t => {
    if (newStatusFilter === 'all') return true;
    if (newStatusFilter === 'active') return !t.completed;
    if (newStatusFilter === 'completed') return t.completed;
    return true;
  });

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <div>
          <h2 className={`text-2xl font-bold ${isDark ? 'text-white' : 'text-slate-900'}`}>Задачи</h2>
          <p className={isDark ? 'text-slate-400' : 'text-slate-500'}>Контроль дедлайнов и продуктивности команды.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-500/20 active:scale-95"
        >
          <Plus size={20} />
          <span className="font-bold">Создать задачу</span>
        </button>
      </div>

      <div className={`p-4 rounded-2xl border flex flex-wrap gap-4 items-center ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
        <button 
          onClick={() => setNewStatusFilter('all')}
          className={`px-4 py-2 rounded-xl font-medium text-sm transition-all ${newStatusFilter === 'all' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
        >
          Все задачи
        </button>
        <button 
          onClick={() => setNewStatusFilter('active')}
          className={`px-4 py-2 rounded-xl font-medium text-sm transition-all ${newStatusFilter === 'active' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
        >
          В работе
        </button>
        <button 
          onClick={() => setNewStatusFilter('completed')}
          className={`px-4 py-2 rounded-xl font-medium text-sm transition-all ${newStatusFilter === 'completed' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
        >
          Завершенные
        </button>
        <div className="ml-auto">
          <button className={`p-2.5 rounded-xl border hover:bg-slate-50 dark:hover:bg-slate-800 transition-all ${isDark ? 'border-slate-700 text-slate-400' : 'border-slate-200 text-slate-500'}`}>
            <Filter size={18} />
          </button>
        </div>
      </div>

      <div className={`rounded-2xl border overflow-hidden shadow-sm ${isDark ? 'bg-slate-900 border-slate-800' : 'bg-white border-slate-200'}`}>
        <div className="divide-y divide-slate-100 dark:divide-slate-800">
          {filteredTasks.map(task => (
            <div key={task.id} className="p-5 flex items-center gap-4 hover:bg-slate-50/50 dark:hover:bg-slate-800/30 transition-colors group">
              <button 
                onClick={() => toggleTask(task.id)}
                className={`transition-all transform hover:scale-110 ${task.completed ? 'text-emerald-500' : 'text-slate-300 dark:text-slate-600 hover:text-indigo-500'}`}
              >
                {task.completed ? <CheckCircle2 size={26} /> : <Circle size={26} />}
              </button>

              <div className="flex-1">
                <h4 className={`text-sm font-bold transition-all ${task.completed ? 'line-through text-slate-400' : isDark ? 'text-white' : 'text-slate-900'}`}>
                  {task.title}
                </h4>
                <div className="flex flex-wrap items-center gap-4 mt-2">
                  <span className="flex items-center gap-1.5 text-[10px] font-medium text-slate-500">
                    <Clock size={12} className="text-indigo-500" />
                    Дедлайн: {task.dueDate}
                  </span>
                  <span className={`px-2 py-0.5 rounded-lg text-[10px] font-bold ${
                    task.priority === 'Высокий' ? 'bg-rose-100 text-rose-600' : 
                    task.priority === 'Средний' ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'
                  }`}>
                    {task.priority}
                  </span>
                  <span className="flex items-center gap-1 text-[10px] text-slate-400 font-medium">
                    <User size={12} /> {task.assignedTo}
                  </span>
                </div>
              </div>

              <button className="p-2 opacity-0 group-hover:opacity-100 text-slate-400 hover:text-indigo-500 transition-all rounded-lg hover:bg-indigo-50 dark:hover:bg-indigo-900/20">
                <MoreHorizontal size={20} />
              </button>
            </div>
          ))}
          {filteredTasks.length === 0 && (
            <div className="p-12 text-center text-slate-500 italic">Задачи отсутствуют</div>
          )}
        </div>
      </div>

      {/* Modal Add Task */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-md animate-in fade-in duration-300">
          <div className={`max-w-md w-full p-8 rounded-3xl border shadow-2xl animate-in zoom-in-95 duration-300 ${isDark ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-100'}`}>
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-2xl font-bold">Новое поручение</h3>
              <button 
                onClick={() => setIsModalOpen(false)}
                className={`p-2 rounded-xl hover:${isDark ? 'bg-slate-800' : 'bg-slate-100'} transition-colors`}
              >
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleAddTask} className="space-y-6">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Что нужно сделать? *</label>
                <input 
                  required
                  placeholder="Описать задачу кратко и ясно..." 
                  className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                  value={newTask.title}
                  onChange={e => setNewTask({...newTask, title: e.target.value})}
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Срок выполнения</label>
                  <input 
                    type="date"
                    className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                    value={newTask.dueDate}
                    onChange={e => setNewTask({...newTask, dueDate: e.target.value})}
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Приоритет</label>
                  <select 
                    className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                    value={newTask.priority}
                    onChange={e => setNewTask({...newTask, priority: e.target.value as any})}
                  >
                    <option value="Низкий">Низкий</option>
                    <option value="Средний">Средний</option>
                    <option value="Высокий">Высокий</option>
                  </select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Исполнитель</label>
                <select 
                  required
                  className={`w-full p-3.5 rounded-xl border text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${isDark ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-50 border-slate-200'}`}
                  value={newTask.assignedTo}
                  onChange={e => setNewTask({...newTask, assignedTo: e.target.value})}
                >
                  <option value="">Выберите сотрудника...</option>
                  {team.map(member => (
                    <option key={member.id} value={member.name}>{member.name} ({member.role})</option>
                  ))}
                </select>
              </div>

              <button className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold hover:bg-indigo-700 transition-all shadow-xl shadow-indigo-500/30 active:scale-95">
                Поставить задачу
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default TasksList;

